<!doctype html><html lang="bn"><head><meta charset="utf-8"><style>body{font-family:"Noto Sans Bengali",sans-serif;font-size:12px;color:#173e36}h1{font-size:24px}table{width:100%;border-collapse:collapse;margin:20px 0}td,th{border-bottom:1px solid #d9dfd3;padding:9px;text-align:left}.right{text-align:right}</style></head><body><h1>{{ $order->organization->name }}</h1><p>চালান / Invoice · {{ $order->number }}</p><p>{{ $order->branch->name }} · {{ $order->created_at->format('d M Y') }}</p><p>{{ $order->customer_name }}<br>{{ $order->phone }}<br>{{ $order->address }}</p><table><tr><th>বিবরণ / Item</th><th>Qty</th><th>{{ __('Price') }}</th><th>মোট / Total</th></tr>@foreach($order->items as $item)<tr><td>{{ $item->description }}</td><td>{{ $item->quantity }}</td><td>BDT {{ number_format($item->unit_price/100,2) }}</td><td>BDT {{ number_format($item->quantity*$item->unit_price/100,2) }}</td></tr>@endforeach</table><p class="right">Delivery: BDT {{ number_format($order->shipping/100,2) }}<br><strong>Total: BDT {{ number_format($order->total/100,2) }}</strong><br>Collected: BDT {{ number_format($order->paid/100,2) }}</p><p>ধন্যবাদ। Thank you.</p></body></html>